import { useEffect, useMemo, useRef } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'motion/react';
import {
  ArrowRight,
  ArrowUpRight,
  BookOpen,
  ChevronDown,
  Layers3,
  Loader2,
  Quote,
  ShieldCheck,
  ShoppingBag,
  Sparkles,
  Star,
} from 'lucide-react';
import { LocalizedPrice } from '../store/LocalizedPrice';
import { LocaleCurrencyPicker } from '../store/LocaleCurrencyPicker';
import { PublicStoreFooter } from '../store/PublicStoreChrome';

interface StorefrontFeedLayoutProps {
  business: any;
  content: any;
  plans: any[];
  products: any[];
  reviews: any[];
  reviewStats: {
    count: number;
    reviewerCount: number;
    average: number;
  };
  hasMoreProducts: boolean;
  loadingMoreProducts: boolean;
  loadMoreError: string | null;
  onLoadMore: () => void;
  onTrackProduct: (productId: string) => void;
  onSubscribe: (planId: string) => void;
}

const firstListingImage = (product: Record<string, unknown>): string | null => {
  const direct = [product.image_url, product.thumbnail, product.image]
    .find((value) => typeof value === 'string' && value.trim());
  if (typeof direct === 'string') return direct.trim();

  if (Array.isArray(product.images)) {
    const image = product.images.find((value) => typeof value === 'string' && value.trim());
    return typeof image === 'string' ? image.trim() : null;
  }

  if (typeof product.images === 'string' && product.images.trim()) {
    try {
      const parsed = JSON.parse(product.images);
      if (Array.isArray(parsed)) {
        const image = parsed.find((value) => typeof value === 'string' && value.trim());
        return typeof image === 'string' ? image.trim() : null;
      }
    } catch {
      return null;
    }
  }

  return null;
};

const publishedLabel = (value: unknown) => {
  if (typeof value !== 'string' || !value) return 'Published on Wersee';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return 'Published on Wersee';
  return new Intl.DateTimeFormat('en', {
    month: 'short',
    day: 'numeric',
    year: date.getFullYear() === new Date().getFullYear() ? undefined : 'numeric',
  }).format(date);
};

const StoreIdentity = ({ business, compact = false }: { business: any; compact?: boolean }) => (
  <div className="flex min-w-0 items-center gap-3">
    <div className={`${compact ? 'h-10 w-10 rounded-xl' : 'h-12 w-12 rounded-2xl'} flex shrink-0 items-center justify-center overflow-hidden border border-white/10 bg-white/[0.06] text-lg font-black text-white shadow-[0_12px_32px_rgba(0,0,0,0.3)]`}>
      {business.logo_url ? (
        <img src={business.logo_url} alt="" className="h-full w-full object-cover" referrerPolicy="no-referrer" />
      ) : (
        String(business.name || 'S').slice(0, 1).toUpperCase()
      )}
    </div>
    <div className="min-w-0">
      <p className={`${compact ? 'text-sm' : 'text-base'} truncate font-semibold tracking-[-0.025em] text-white`}>
        {business.name}
      </p>
      <p className="mt-0.5 truncate text-[10px] font-semibold uppercase tracking-[0.2em] text-white/32">
        Storefront
      </p>
    </div>
  </div>
);

export const StorefrontFeedLayout = ({
  business,
  content,
  plans,
  products,
  reviews,
  reviewStats,
  hasMoreProducts,
  loadingMoreProducts,
  loadMoreError,
  onLoadMore,
  onTrackProduct,
  onSubscribe,
}: StorefrontFeedLayoutProps) => {
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const navigation = useMemo(() => [
    { label: 'The feed', href: '#storefront-feed', icon: Sparkles },
    { label: 'New releases', href: '#storefront-feed', icon: Layers3 },
    { label: 'Our story', href: '#storefront-story', icon: BookOpen },
    ...(plans.length ? [{ label: 'Memberships', href: '#storefront-plans', icon: ShoppingBag }] : []),
    { label: 'Customer notes', href: '#storefront-reviews', icon: Star },
  ], [plans.length]);

  useEffect(() => {
    if (!hasMoreProducts || loadingMoreProducts || loadMoreError) return;
    const target = loadMoreRef.current;
    if (!target || typeof IntersectionObserver === 'undefined') return;

    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) onLoadMore();
    }, { rootMargin: '700px 0px' });

    observer.observe(target);
    return () => observer.disconnect();
  }, [hasMoreProducts, loadMoreError, loadingMoreProducts, onLoadMore]);

  const heroImage = content.hero_image_url || business.logo_url || null;
  const heroTitle = content.hero_title || business.name;
  const heroSubtitle = content.hero_subtitle || business.description || 'Explore this independent storefront on Wersee.';

  return (
    <div className="min-h-[100dvh] bg-[#050506] text-white selection:bg-violet-400/30">
      <aside className="fixed inset-y-0 left-0 z-[90] hidden w-[284px] flex-col border-r border-white/[0.07] bg-[#08080a]/95 px-5 py-6 backdrop-blur-2xl lg:flex">
        <StoreIdentity business={business} />

        <nav aria-label={`${business.name} storefront`} className="mt-12 space-y-1.5">
          {navigation.map(({ label, href, icon: Icon }, index) => (
            <a
              key={`${label}-${index}`}
              href={href}
              className={`group flex min-h-11 items-center gap-3 rounded-2xl px-3.5 text-sm font-medium outline-none transition focus-visible:ring-2 focus-visible:ring-violet-400 ${index === 0 ? 'bg-white/[0.08] text-white shadow-[inset_0_1px_rgba(255,255,255,0.04)]' : 'text-white/48 hover:bg-white/[0.045] hover:text-white'}`}
            >
              <Icon className={`h-[18px] w-[18px] ${index === 0 ? 'text-violet-300' : 'text-white/36 group-hover:text-white/70'}`} />
              {label}
            </a>
          ))}
        </nav>

        <div className="mt-auto rounded-[24px] border border-white/[0.07] bg-white/[0.035] p-4">
          <div className="flex items-center gap-2 text-xs font-semibold text-white/65">
            <ShieldCheck className="h-4 w-4 text-emerald-300" />
            Secure Wersee checkout
          </div>
          <p className="mt-2 text-xs leading-5 text-white/30">
            Clear pricing and buyer support remain available on every release.
          </p>
          <Link to="/buyer-protection" className="mt-3 inline-flex items-center gap-1 text-xs font-semibold text-white/55 hover:text-white">
            Buyer protection <ArrowUpRight className="h-3 w-3" />
          </Link>
        </div>
      </aside>

      <div className="lg:pl-[284px]">
        <header className="sticky top-0 z-[80] border-b border-white/[0.07] bg-[#070708]/88 px-4 py-3 backdrop-blur-2xl lg:hidden">
          <div className="flex items-center justify-between gap-4">
            <StoreIdentity business={business} compact />
            <LocaleCurrencyPicker dark className="shrink-0" />
          </div>
          <nav aria-label={`${business.name} storefront sections`} className="mt-3 flex gap-1.5 overflow-x-auto pb-0.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
            {navigation.map(({ label, href }, index) => (
              <a
                key={`${label}-mobile-${index}`}
                href={href}
                className={`min-h-9 shrink-0 rounded-full border px-3.5 py-2 text-xs font-semibold ${index === 0 ? 'border-white/10 bg-white/10 text-white' : 'border-white/[0.06] bg-white/[0.025] text-white/45'}`}
              >
                {label}
              </a>
            ))}
          </nav>
        </header>

        <main>
          <section className="relative mx-auto max-w-[1440px] px-3 pb-7 pt-3 sm:px-6 sm:pt-6 xl:px-9">
            <motion.div
              initial={{ opacity: 0, y: 18 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.7, ease: [0.22, 1, 0.36, 1] }}
              className="relative min-h-[480px] overflow-hidden rounded-[30px] border border-white/[0.08] bg-[#0d0d10] shadow-[0_32px_100px_rgba(0,0,0,0.5)] sm:min-h-[560px] sm:rounded-[40px]"
            >
              {heroImage ? (
                <img
                  src={heroImage}
                  alt=""
                  className="absolute inset-0 h-full w-full object-cover opacity-70"
                  referrerPolicy="no-referrer"
                />
              ) : null}
              <div className="absolute inset-0 bg-[radial-gradient(circle_at_78%_18%,rgba(139,92,246,0.28),transparent_36%),linear-gradient(90deg,rgba(5,5,6,0.96)_0%,rgba(5,5,6,0.72)_48%,rgba(5,5,6,0.3)_100%)]" />
              <div className="absolute inset-x-0 bottom-0 h-48 bg-gradient-to-t from-[#08080a] to-transparent" />

              <div className="relative z-10 flex min-h-[480px] max-w-3xl flex-col justify-end p-6 sm:min-h-[560px] sm:p-12 lg:p-16">
                <p className="mb-5 flex items-center gap-2 text-[11px] font-bold uppercase tracking-[0.25em] text-violet-200/80">
                  <span className="h-1.5 w-1.5 rounded-full bg-violet-300 shadow-[0_0_18px_rgba(196,181,253,0.95)]" />
                  Curated storefront
                </p>
                <h1 className="max-w-3xl text-5xl font-semibold leading-[0.95] tracking-[-0.065em] text-white sm:text-7xl lg:text-[88px]">
                  {heroTitle}
                </h1>
                <p className="mt-6 max-w-2xl text-base leading-7 text-white/55 sm:text-lg sm:leading-8">
                  {heroSubtitle}
                </p>
                <div className="mt-8 flex flex-wrap gap-3">
                  <a href="#storefront-feed" className="inline-flex min-h-12 items-center gap-2 rounded-full bg-white px-5 text-sm font-bold text-black transition hover:scale-[1.02]">
                    Enter the feed <ChevronDown className="h-4 w-4" />
                  </a>
                  <a href="#storefront-story" className="inline-flex min-h-12 items-center rounded-full border border-white/12 bg-black/20 px-5 text-sm font-semibold text-white/70 backdrop-blur-md transition hover:bg-white/10 hover:text-white">
                    Meet the store
                  </a>
                </div>
              </div>

              <div className="absolute right-5 top-5 z-10 hidden sm:block">
                <LocaleCurrencyPicker dark className="rounded-full border border-white/10 bg-black/35 px-3 py-2 backdrop-blur-xl" />
              </div>
            </motion.div>
          </section>

          <section className="mx-auto grid max-w-[1260px] items-start gap-6 px-3 pb-16 sm:px-6 lg:grid-cols-[minmax(0,760px)_minmax(280px,360px)] lg:px-8 xl:gap-8">
            <div id="storefront-feed" className="scroll-mt-28 space-y-5">
              <div className="flex items-end justify-between gap-5 px-1 pb-2 pt-3">
                <div>
                  <p className="text-[10px] font-bold uppercase tracking-[0.24em] text-violet-300/65">Live catalog</p>
                  <h2 className="mt-2 text-3xl font-semibold tracking-[-0.045em] text-white sm:text-4xl">Latest releases</h2>
                </div>
                <span className="hidden rounded-full border border-white/[0.07] bg-white/[0.025] px-3 py-1.5 text-xs text-white/35 sm:inline-flex">
                  Scroll to explore
                </span>
              </div>

              {products.length ? products.map((product, index) => {
                const image = firstListingImage(product);
                const description = product.short_description || product.description || null;
                const ratingCount = Number(product.rating_count || 0);
                const ratingAverage = Number(product.rating_avg || 0);

                return (
                  <motion.article
                    key={product.id}
                    initial={{ opacity: 0, y: 24 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    viewport={{ once: true, margin: '-80px' }}
                    transition={{ duration: 0.55, delay: Math.min(index, 3) * 0.04 }}
                    className="overflow-hidden rounded-[28px] border border-white/[0.075] bg-[#0d0d0f] shadow-[0_22px_70px_rgba(0,0,0,0.28)] [content-visibility:auto] [contain-intrinsic-size:auto_680px] sm:rounded-[34px]"
                  >
                    <div className="flex items-center gap-3 px-5 py-4 sm:px-6 sm:py-5">
                      <div className="flex h-10 w-10 shrink-0 items-center justify-center overflow-hidden rounded-2xl border border-white/10 bg-white/[0.05] text-sm font-black">
                        {business.logo_url ? <img src={business.logo_url} alt="" className="h-full w-full object-cover" /> : String(business.name || 'S').slice(0, 1).toUpperCase()}
                      </div>
                      <div className="min-w-0">
                        <p className="truncate text-sm font-semibold text-white">{business.name}</p>
                        <p className="mt-0.5 text-xs text-white/32">{publishedLabel(product.created_at)}</p>
                      </div>
                      <span className="ml-auto rounded-full border border-violet-300/10 bg-violet-400/[0.07] px-3 py-1.5 text-[10px] font-bold uppercase tracking-[0.14em] text-violet-200/65">
                        Release
                      </span>
                    </div>

                    <div className="px-5 pb-5 sm:px-6 sm:pb-6">
                      <h3 className="text-2xl font-semibold leading-tight tracking-[-0.035em] text-white sm:text-[30px]">{product.title}</h3>
                      {description ? <p className="mt-3 line-clamp-3 text-sm leading-6 text-white/43 sm:text-[15px] sm:leading-7">{description}</p> : null}
                    </div>

                    {image ? (
                      <Link to={`/listing/${product.id}`} onClick={() => onTrackProduct(String(product.id))} className="group block overflow-hidden border-y border-white/[0.06] bg-white/[0.02]">
                        <img
                          src={image}
                          alt={product.title}
                          loading="lazy"
                          decoding="async"
                          className="max-h-[680px] w-full object-cover transition duration-700 ease-out group-hover:scale-[1.015]"
                        />
                      </Link>
                    ) : null}

                    <div className="flex flex-wrap items-center gap-3 px-5 py-4 sm:px-6 sm:py-5">
                      <div className="mr-auto">
                        <LocalizedPrice
                          amount={product.price}
                          baseCurrency={product.currency || product.base_currency || 'EUR'}
                          showOriginal={false}
                          className="text-lg font-bold tracking-[-0.025em] text-white"
                        />
                        {ratingCount > 0 && ratingAverage > 0 ? (
                          <p className="mt-1 flex items-center gap-1.5 text-xs text-white/35">
                            <Star className="h-3.5 w-3.5 fill-amber-300 text-amber-300" />
                            {ratingAverage.toFixed(1)} from {ratingCount} {ratingCount === 1 ? 'review' : 'reviews'}
                          </p>
                        ) : (
                          <p className="mt-1 text-xs text-white/28">Secure checkout on Wersee</p>
                        )}
                      </div>
                      <Link
                        to={`/listing/${product.id}`}
                        onClick={() => onTrackProduct(String(product.id))}
                        className="inline-flex min-h-11 items-center gap-2 rounded-full bg-white px-4 text-sm font-bold text-black transition hover:bg-violet-100"
                      >
                        View release <ArrowRight className="h-4 w-4" />
                      </Link>
                    </div>
                  </motion.article>
                );
              }) : (
                <div className="rounded-[30px] border border-dashed border-white/10 bg-white/[0.02] px-6 py-20 text-center">
                  <ShoppingBag className="mx-auto h-7 w-7 text-white/22" />
                  <h3 className="mt-5 text-lg font-semibold text-white">No releases yet</h3>
                  <p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-white/35">This storefront has not published any products or services yet.</p>
                </div>
              )}

              <div ref={loadMoreRef} className="flex min-h-20 items-center justify-center py-4" aria-live="polite">
                {loadingMoreProducts ? (
                  <span className="flex items-center gap-2 text-sm text-white/35"><Loader2 className="h-4 w-4 animate-spin" /> Loading more releases</span>
                ) : loadMoreError ? (
                  <button type="button" onClick={onLoadMore} className="min-h-11 rounded-full border border-red-400/15 bg-red-400/[0.06] px-5 text-sm font-semibold text-red-200/75 hover:bg-red-400/10">
                    Try loading more again
                  </button>
                ) : hasMoreProducts ? (
                  <button type="button" onClick={onLoadMore} className="min-h-11 rounded-full border border-white/[0.07] bg-white/[0.025] px-5 text-sm font-semibold text-white/42 hover:bg-white/[0.06] hover:text-white">
                    Load more releases
                  </button>
                ) : products.length ? (
                  <span className="text-xs font-medium uppercase tracking-[0.2em] text-white/20">You are all caught up</span>
                ) : null}
              </div>
            </div>

            <aside className="space-y-5 lg:sticky lg:top-7">
              <section id="storefront-story" className="scroll-mt-28 rounded-[28px] border border-white/[0.075] bg-[#0d0d0f] p-6">
                <p className="text-[10px] font-bold uppercase tracking-[0.22em] text-violet-300/65">Behind the storefront</p>
                <h2 className="mt-3 text-2xl font-semibold tracking-[-0.04em] text-white">Our story</h2>
                <p className="mt-4 text-sm leading-6 text-white/42">
                  {content.about_text || business.description || 'This storefront has not added its story yet.'}
                </p>
                {content.about_image_url ? <img src={content.about_image_url} alt={`About ${business.name}`} loading="lazy" decoding="async" className="mt-5 aspect-[4/3] w-full rounded-2xl object-cover" /> : null}
              </section>

              {plans.length ? (
                <section id="storefront-plans" className="scroll-mt-28 rounded-[28px] border border-white/[0.075] bg-[#0d0d0f] p-6">
                  <p className="text-[10px] font-bold uppercase tracking-[0.22em] text-cyan-200/60">Go deeper</p>
                  <h2 className="mt-3 text-2xl font-semibold tracking-[-0.04em] text-white">Memberships</h2>
                  <div className="mt-5 space-y-3">
                    {plans.slice(0, 3).map((plan) => (
                      <button
                        key={plan.id}
                        type="button"
                        onClick={() => onSubscribe(String(plan.id))}
                        className="group w-full rounded-2xl border border-white/[0.07] bg-white/[0.025] p-4 text-left transition hover:border-white/15 hover:bg-white/[0.05]"
                      >
                        <span className="flex items-start justify-between gap-3">
                          <span className="min-w-0">
                            <span className="block truncate text-sm font-semibold text-white">{plan.name}</span>
                            <span className="mt-1 block text-xs text-white/32">Billed {plan.interval}</span>
                          </span>
                          <ArrowUpRight className="h-4 w-4 shrink-0 text-white/25 transition group-hover:text-white/70" />
                        </span>
                        <LocalizedPrice amount={plan.price} baseCurrency={plan.currency || business.currency || 'EUR'} className="mt-3 block text-lg font-bold text-white" />
                      </button>
                    ))}
                  </div>
                </section>
              ) : null}

              <section id="storefront-reviews" className="scroll-mt-28 rounded-[28px] border border-white/[0.075] bg-[#0d0d0f] p-6">
                <p className="text-[10px] font-bold uppercase tracking-[0.22em] text-amber-200/60">Customer notes</p>
                <div className="mt-3 flex items-end justify-between gap-4">
                  <h2 className="text-2xl font-semibold tracking-[-0.04em] text-white">Reviews</h2>
                  {reviewStats.count ? (
                    <span className="flex items-center gap-1.5 text-sm font-bold text-white"><Star className="h-4 w-4 fill-amber-300 text-amber-300" /> {reviewStats.average.toFixed(1)}</span>
                  ) : null}
                </div>
                {reviews.length ? (
                  <div className="mt-5 space-y-3">
                    {reviews.slice(0, 2).map((review) => (
                      <article key={review.id} className="rounded-2xl border border-white/[0.06] bg-white/[0.025] p-4">
                        <Quote className="h-4 w-4 text-white/22" />
                        <p className="mt-3 line-clamp-4 text-sm leading-6 text-white/47">{review.comment || 'A rating was submitted without a written comment.'}</p>
                        <p className="mt-3 text-xs font-semibold text-white/62">{review.profiles?.full_name || review.profiles?.username || 'Verified customer'}</p>
                      </article>
                    ))}
                    <p className="px-1 text-xs text-white/27">{reviewStats.count} saved {reviewStats.count === 1 ? 'review' : 'reviews'} on Wersee</p>
                  </div>
                ) : (
                  <p className="mt-4 text-sm leading-6 text-white/35">No customer reviews have been published for this storefront yet.</p>
                )}
              </section>
            </aside>
          </section>
        </main>

        <PublicStoreFooter sellerName={business.name} />
      </div>
    </div>
  );
};
